import{z as p,x as P,o as t,c as B,q as i,j as l,D as e,d as s,s as n,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"PTP","description":"","frontmatter":{"title":"PTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ptp-precision-time.md","filePath":"cs/ptp-precision-time.md","lastUpdated":1791063341000}'),d={name:"cs/ptp-precision-time.md"};function T(c,a,A,h,m,_){const E=P("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="ptp" tabindex="-1">PTP <a class="header-anchor" href="#ptp" aria-label="Permalink to &quot;PTP&quot;">​</a></h1><div class="epigraph"><p>PTP 用硬件时间戳与边界/透明时钟补偿交换延迟，把同步推进到微秒–纳秒，服务交易所与 5G RAN，不是 NTP 的换肤。</p><footer>—— 据 IEEE 1588 PTP；ITU-T 电信剖面整理</footer></div><p><a href="/cs/ntp">NTP</a> 到毫秒。<a href="/cs/cellular-ran-core">5G RAN</a> 要更紧。<a href="/cs/ntp">上一课</a> 的软件时间戳被内核与网卡抖动限制。缺口是 <strong>PTP</strong>：硬件戳、BC/TC。本课不把 FTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易所、基站、数据中心快照要亚微秒。PTP：Sync/Follow_Up/Delay 消息，网卡在 PHY 打戳。边界时钟每跳重新主从；透明时钟把驻留时间写进修正域，避免交换机排队把 NTP 式估计毁掉——直接对应缓冲膨胀与 HOL。要全程支持，一条普通交换机就会毁掉精度。</p><p>不要把 PTP 写成区块链时间。</p><p><span class="marginnote">IEEE 1588。Profile（默认/电信/电力）选定时与消息率。本课不点名交易品种。</span></p><p><span class="marginnote">透明时钟的「修正域」像快递单上的中转记录：交换机在报文里补一句「在我这儿排队停留了 8.3 微秒」，从钟据此把这段驻留从延迟估计里扣掉。边界时钟则是另一种思路——干脆每台中转设备自己当分站钟，一跳一跳重新对时。</span></p><h3 id="要全程硬件戳" tabindex="-1">要全程硬件戳 <a class="header-anchor" href="#要全程硬件戳" aria-label="Permalink to &quot;要全程硬件戳&quot;">​</a></h3><p>透明时钟补偿驻留，普通交换机毁掉精度。服务 RAN 与机房，不服务随意公网主机。与 NTP 不是换肤。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 NTP 软件戳 vs PTP 硬件戳。画：主时钟 → 支持 PTP 的交换 → 从时钟。与 URLLC：空口同步可源于同一时间底座。</p>',12)),(t(),l(o,null,{default:e(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GM%5B%22%E5%A4%A7%E4%B8%BB%E9%92%9F%22%5D%20--%3E%20BC%5B%22%E8%BE%B9%E7%95%8C%E6%97%B6%E9%92%9F%22%5D%0A%20%20GM%20--%3E%20TC%5B%22%E9%80%8F%E6%98%8E%E6%97%B6%E9%92%9F%E4%BF%AE%E6%AD%A3%E9%A9%BB%E7%95%99%22%5D%0A%20%20TC%20--%3E%20SL%5B%22%E4%BB%8E%E6%97%B6%E9%92%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[s("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"RoCE 时间戳、Wi‑Fi TSF 是别的钟。安全：未认证 PTP 可被欺骗，要授时网络隔离。ECMP 不对称伤害 delay 测量，PTP 域常固定路径。卫星有传播，但地面 RAN 回传用光纤 PTP。",-1)),(t(),l(o,null,{default:e(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E4%B8%BB%E9%92%9F%E5%8F%91%20Sync%20%E8%AE%B0%20t1%22%5D%20--%3E%20S1%5B%22%E4%BB%8E%E9%92%9F%E6%94%B6%E5%88%B0%E8%AE%B0%20t2%22%5D%0A%20%20S1%20--%3E%20M2%5B%22%E4%B8%BB%E9%92%9F%E8%A1%A5%E5%8F%91%20Follow_Up%20%E4%BA%A4%E5%87%BA%20t1%22%5D%0A%20%20S2%5B%22%E4%BB%8E%E9%92%9F%E5%8F%91%20Delay_Req%20%E8%AE%B0%20t3%22%5D%20--%3E%20M3%5B%22%E4%B8%BB%E9%92%9F%E6%94%B6%E5%88%B0%E8%AE%B0%20t4%22%5D%0A%20%20M3%20--%3E%20R%5B%22%E4%BB%8E%E9%92%9F%E7%94%A8%20t1%20t2%20t3%20t4%20%E8%A7%A3%E5%87%BA%E9%92%9F%E5%B7%AE%E4%B8%8E%E8%B7%AF%E5%BE%84%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">上图回答「钟差是怎么算出来的」：代入数字，\\(t_2 - t_1 = 1000\\) ns、\\(t_4 - t_3 = 800\\) ns，则平均路径延迟 \\((1000+800)/2 = 900\\) ns，从钟比主钟快了 \\(1000 - 900 = 100\\) ns，照此微调本地钟即可。</span></p><p><span class="marginnote">初学者容易以为精度只由两端网卡决定。实际上中途一台普通交换机的排队抖动就有几十微秒，比微秒级目标高几个量级——这正是「一台混入的交换机毁掉全程精度」的原因，也是 ECMP 多路径要被固定掉的原因。</span></p><p>与容量无关：同步是控制，不是 \\(C\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 White Rabbit 的全部。FTP 被动模式是下一课。后课默认：微秒级同步要 PTP 与支持的交换；NTP 不够。</p><p>在公网互联网上跑 PTP 没有 hop-by-hop 支持。</p><p><span class="marginnote">给个数的感觉：NTP 公网能做到毫秒（\\(10^6\\) 纳秒）级，PTP 目标是亚微秒（\\(10^2\\) 纳秒）级——差三四个数量级。这就好比一把尺子刻度到毫米，另一把到微米；量刻度的方式（软件读时钟 vs 网卡 PHY 硬件打戳）完全不同。</span></p><p>下一课<a href="/cs/ftp-passive">FTP 被动模式</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬件时间戳 + 交换补偿驻留。</li><li>全程 PTP 感知，否则退回 NTP 精度。</li><li>服务 RAN 与机房，不服务随意主机。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 1588。</li></ul>',10))])}const F=p(d,[["render",T]]);export{u as __pageData,F as default};
